s={'synthesis_id':'ingredient-applesauce-v1','family':'ingredient','slug':'applesauce','title':'Applesauce','display_title':'Applesauce','version':1,'date':'2026-10-22','description':'Metals in applesauce: FDA prepared-food measurements, reporting limits, ingredient controls and the distinct cinnamon-pouch outbreak.','lede':'','article_lede':False,'citation_style':'compact','citation_placement':'sentence','sections':[],'section_headings':headings,'universal_faqs':{'title':'Applesauce FAQs','aliases':[]},'scope':{'analytes':'Pb, Cd, tAs, tHg, Ni, Cr, U; source totals distinct from species','material_form':'FDA bottled applesauce and baby-food applesauce; cinnamon-containing finished puree distinct','basis':'Source prepared-food mass basis; ppb = µg/kg; no moisture conversion','geography_market':'United States collection markets, not orchard origin','period':'FDA FY2018–FY2020; outbreak 2023–2024; national report published 2025','stage':'Finished-food measurement, ingredient attribution, testing and recall','population_route':'Dietary ingestion; children in outbreak, no individualized serving calculation','comparator_outcome':'Named numerical form/composite contrasts; reporting bounds; no causal processing, safety or origin grade'},'search':{'status':'in_progress','scope':'Existing applesauce relationships and selected exact prepared-food primary verification; not systematic whole-literature review','protocol_ref':'data/evidence/contracts/ingredient-rollout-2026-10-22/applesauce/source-review.json','record_refs':['data/evidence/contracts/ingredient-rollout-2026-10-22/applesauce/source-review.json','data/evidence/contracts/ingredient-rollout-2026-10-22/applesauce/source-observations.json'],'screening_ref':'data/evidence/contracts/ingredient-rollout-2026-10-22/applesauce/source-review.json','searched_through':None,'limitations':['Additional apple-only baby-food extraction unfinished','Current primary legal applicability unverified','Outcome-level appraisal incomplete; no complete question-level systematic searches','External mounted library offline; official downloaded FDA and retained CDC originals used'],'unresolved_access':[]}}
